INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 7, 'theory', 'TCP: Handshake, Byte Numbering, and Closing a Connection');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 7, 0, 'Which segments make up the setup of a TCP connection?', '["ACK, ACK, FIN", "SYN, SYN-ACK, ACK", "SYN, FIN, RST", "SYN, ACK"]', 1, 'The three-way handshake: the client sends SYN, the server SYN-ACK, the client ACK.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 7, 1, 'The client sent a segment with number 1000 and 100 bytes of data. What ACK value will the server reply with?', '["1000", "100", "1001", "1100"]', 3, 'ACK is the number of the next expected byte: 1000 + 100 = 1100.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 7, 2, 'When connecting to a port, an RST came back instead of a reply. What does this mean?', '["The host is alive, but nobody listens on this port", "A firewall swallows the packets", "The server is overloaded", "You need to repeat the SYN"]', 0, 'A closed port answers with RST; silence is a sign of a filter or loss.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 7, 3, 'What does the sender do after receiving three identical ACKs in a row?', '["Closes the connection", "Reduces the MSS", "Resends the lost segment without waiting for the timer", "Starts the handshake over"]', 2, 'Duplicate ACKs mean one segment is missing while the following ones arrived: fast retransmit.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 7, 4, 'Why is the TIME_WAIT state kept after a connection is closed?', '["To save the password", "To close the port on the server", "To let the server restart", "So that late segments do not end up in a new connection with the same ports"]', 3, 'Segments of the old connection may still wander the network; a minute of waiting filters them out.');
